1	/**
2	 * The boot fact for one production output root of the
3	 * `angular-tiny-translator-v0-12-0` cell.
4	 *
5	 * u19d's finding was that the migrated lane's build lanes were green and
6	 * deterministic while the artifact they emitted threw before Angular
7	 * bootstrapped — a failure invisible to every check the build lanes perform,
8	 * and visible in a browser within a second of loading the page. A build record
9	 * that claims a green migrated lane without opening the artifact once is a
10	 * record that can be contradicted the same way again.
11	 *
12	 * So this is the narrowest browser measurement that would have caught it: serve
13	 * the output root over loopback, load the initial route, and read back whether
14	 * Angular's own root component rendered the home surface — with every page
15	 * error and console error the load produced recorded exactly, whether the
16	 * surface appeared or not.
17	 *
18	 * It is deliberately not a journey. No gesture is performed, no seam is mocked
19	 * and nothing is asserted about behaviour; the four uncalibrated facts the
20	 * Witness proof owes this vertical remain uncalibrated and are not touched
21	 * here. What this establishes is one fact — the bundle evaluates and the
22	 * application mounts — and that is the exact fact u19d found missing.
23	 */
24	
25	import { join, resolve } from 'pathe';
26	import { joinURL } from 'ufo';
27	import type { BrowserConsoleMessage, BrowserPageError } from '@async/witness';
28	import { createPlaywrightWitnessHost } from './playwright-host.ts';
29	import { startStaticServer } from './real-app-run.ts';
30	
31	const root = resolve(import.meta.dirname, '../../../..');
32	const chromiumExecutable = join(
33		root,
34		'.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell',
35	);
36	
37	/**
38	 * The route the application's own router treats as home, and the element the
39	 * home surface renders its title into. Both are read out of the served bundle
40	 * by the journey this vertical already carries; they are restated here because
41	 * a boot check that waited for nothing in particular would pass on a blank
42	 * page.
43	 */
44	export const TINY_TRANSLATOR_HOME_ROUTE = '/#/home';
45	export const TINY_TRANSLATOR_HOME_SELECTOR = '#apptitle';
46	export const TINY_TRANSLATOR_HOME_TITLE = 'Tiny Translator';
47	
48	export type BootObservation = Readonly<{
49		/** The output root served, as handed in. */
50		laneRoot: string;
51		/** The page URL, with the ephemeral loopback origin normalized away. */
52		url: string;
53		/** Whether the home surface rendered its title within the budget. */
54		booted: boolean;
55		/** The text the home selector carried, or null when it never appeared. */
56		renderedTitle: string | null;
57		/** Every uncaught page error, in observation order. */
58		pageErrors: readonly string[];
59		/** Every console error, in observation order. */
60		consoleErrors: readonly string[];
61		/** The refusal, when the surface did not render. */
62		refusal: string | null;
63	}>;
64	
65	const PLACEHOLDER_ORIGIN = '{production-static-origin}';
66	
67	/** How long the home surface is given to render before the load is a failure. */
68	const BOOT_TIMEOUT_MS = 10_000;
69	
70	function normalizeOrigin(text: string, origin: string): string {
71		return text.split(origin).join(PLACEHOLDER_ORIGIN);
72	}
73	
74	/**
75	 * Load one production output root in a browser and report whether the
76	 * application mounted.
77	 *
78	 * The browser context is the same one the vertical's Witness runs under, with
79	 * one deliberate exception: service workers are left at the host's default
80	 * rather than blocked, because this check makes no claim about them and a
81	 * policy imposed here would produce console errors of its own that the caller
82	 * would then have to account for.
83	 */
84	export async function observeAngularTinyTranslatorBoot(
85		laneRoot: string,
86	): Promise<BootObservation> {
87		const staticServer = await startStaticServer(laneRoot);
88		const host = createPlaywrightWitnessHost({ chromiumExecutable });
89		const pageErrors: string[] = [];
90		const consoleErrors: string[] = [];
91		const url = joinURL(staticServer.origin, TINY_TRANSLATOR_HOME_ROUTE);
92		const session = await host.browser.launch({ headless: true });
93		let booted = false;
94		let renderedTitle: string | null = null;
95		let refusal: string | null = null;
96		try {
97			const page = await session.newPage();
98			page.onPageError((error: BrowserPageError) => pageErrors.push(error.message));
99			page.onConsoleMessage((message: BrowserConsoleMessage) => {
100				if (message.level === 'error') consoleErrors.push(message.text);
101			});
102			await page.goto(url);
103			const expression =
104				`document.querySelector(${JSON.stringify(TINY_TRANSLATOR_HOME_SELECTOR)})` +
105				`?.textContent?.trim() === ${JSON.stringify(TINY_TRANSLATOR_HOME_TITLE)}`;
106			try {
107				await page.waitForExpression(expression, BOOT_TIMEOUT_MS);
108				booted = true;
109			} catch (error) {
110				refusal = error instanceof Error ? error.message : String(error);
111			}
112			const text = await page.evaluate(
113				`document.querySelector(${JSON.stringify(TINY_TRANSLATOR_HOME_SELECTOR)})?.textContent ?? null`,
114			);
115			renderedTitle = typeof text === 'string' ? text.trim() : null;
116			await page.close();
117		} finally {
118			await session.close();
119			await staticServer.close();
120		}
121		return Object.freeze({
122			laneRoot,
123			url: normalizeOrigin(url, staticServer.origin),
124			booted,
125			renderedTitle,
126			pageErrors: Object.freeze(
127				pageErrors.map((message) => normalizeOrigin(message, staticServer.origin)),
128			),
129			consoleErrors: Object.freeze(
130				consoleErrors.map((message) => normalizeOrigin(message, staticServer.origin)),
131			),
132			refusal: refusal === null ? null : normalizeOrigin(refusal, staticServer.origin),
133		});
134	}
135	
136	export async function main(): Promise<void> {
137		const laneRoot = process.argv[2];
138		if (laneRoot === undefined)
139			throw new Error('TinyTranslator boot check requires an output root to serve');
140		const observation = await observeAngularTinyTranslatorBoot(resolve(laneRoot));
141		process.stdout.write(`${JSON.stringify(observation, null, '\t')}\n`);
142		if (!observation.booted) process.exitCode = 1;
143	}
144	
145	if (process.argv[1]?.endsWith('angular-tiny-translator-boot-check.ts'))
146		main().catch((error: unknown) => {
147			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
148			process.exitCode = 1;
149		});
